import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
// No longer import Login/Register directly here, as LoginPage/RegisterPage will do that.
// AuthProvider is correctly set up in src/index.js

import Navbar from './components/Navbar'; // Import the Navbar component

import HomePage from './pages/HomePage';
import LoginPage from './pages/LoginPage';      // Import the page components
import RegisterPage from './pages/RegisterPage'; // Import the page components
import UserDashboard from './components/UserDashboard'; // Kept as direct component for now
import AdminDashboard from './components/AdminDashboard'; // Kept as direct component for now
import UnauthorizedPage from './pages/UnauthorizedPage';
import NotFoundPage from './pages/NotFoundPage';

function App() {
  return (
    <Router>
      <Navbar /> {/* Navbar shown on all pages */}
      <div className="container mx-auto mt-4 px-4"> {/* Add a container for content */}
        <Routes>
          {/* Public Routes */}
          <Route path="/" element={<HomePage />} />
          <Route path="/login" element={<LoginPage />} /> {/* Renders LoginPage */}
          <Route path="/register" element={<RegisterPage />} /> {/* Renders RegisterPage */}

          {/* Protected Routes */}
          <Route
            path="/dashboard" // General dashboard route
            element={
              <ProtectedRoute>
                <UserDashboard /> {/* Specific user dashboard */}
              </ProtectedRoute>
            }
          />
          <Route
            path="/admin" // General admin route
            element={
              <ProtectedRoute adminOnly={true}>
                <AdminDashboard /> {/* Specific admin dashboard */}
              </ProtectedRoute>
            }
          />

          {/* Specific User Dashboard Route (optional, can be consolidated with /dashboard) */}
          <Route
            path="/user/dashboard"
            element={
              <ProtectedRoute>
                <UserDashboard />
              </ProtectedRoute>
            }
          />

          {/* Specific Admin Dashboard Route (optional, can be consolidated with /admin) */}
          <Route
            path="/admin/dashboard"
            element={
              <ProtectedRoute adminOnly={true}>
                <AdminDashboard />
              </ProtectedRoute>
            }
          />

          {/* Access Denied Route */}
          <Route path="/unauthorized" element={<UnauthorizedPage />} />

          {/* 404 Not Found Route */}
          <Route path="*" element={<NotFoundPage />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
